changeSet.sql:
update modeling_warehouse_layer set layer_group = case system_layer_code when 'ODS_RAW' then 'STAGING' when 'ODS_STANDARDIZED' then 'STAGING' when 'STG' then 'STAGING' when 'DWD' then 'COMMON' when 'DWS' then 'COMMON' when 'ADS' then 'APPLICATION' end where layer_group is null;
alter table modeling_warehouse_layer alter column layer_group set not null;
alter table modeling_warehouse_layer add constraint ck_modeling_warehouse_layer_group check (layer_group in ('STAGING', 'COMMON', 'APPLICATION'));
